import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Analytics and Options Tools","description":"","frontmatter":{},"headers":[],"relativePath":"analytics-and-options-tools.md","filePath":"analytics-and-options-tools.md"}'),d={name:"analytics-and-options-tools.md"};function n(s,t,i,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="analytics-and-options-tools" tabindex="-1">Analytics and Options Tools <a class="header-anchor" href="#analytics-and-options-tools" aria-label="Permalink to &quot;Analytics and Options Tools&quot;">​</a></h1><p>Tradeboard ships <strong>18 analytics surfaces</strong> under <code>/tools</code>, covering the options desk, portfolio analysis and backtesting. They run inside your own installation against your broker&#39;s live data, so nothing here depends on an external service.</p><p>These are interactive UI tools rather than API endpoints. Several are backed by the <a href="./api-documentation/v1/data-api/option-chain">Options API</a>, so anything you can see on screen you can also automate.</p><hr><h2 id="options-desk" tabindex="-1">Options Desk <a class="header-anchor" href="#options-desk" aria-label="Permalink to &quot;Options Desk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Path</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Option Chain</strong></td><td><code>/optionchain</code></td><td>Real-time chain with live Greeks, OI data and quick order placement</td></tr><tr><td><strong>Option Greeks</strong></td><td><code>/ivchart</code></td><td>Historical IV, Delta, Theta, Vega and Gamma charts for ATM options</td></tr><tr><td><strong>Max Pain</strong></td><td><code>/maxpain</code></td><td>Max pain strike with the pain distribution across strikes</td></tr><tr><td><strong>IV Smile</strong></td><td><code>/ivsmile</code></td><td>Call and put IV curves, ATM IV and skew analysis</td></tr><tr><td><strong>Vol Surface</strong></td><td><code>/volsurface</code></td><td>3D implied volatility surface across strikes and expiries</td></tr></tbody></table><h2 id="open-interest" tabindex="-1">Open Interest <a class="header-anchor" href="#open-interest" aria-label="Permalink to &quot;Open Interest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Path</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>OI Tracker</strong></td><td><code>/oitracker</code></td><td>CE and PE OI bars, PCR overlay and the ATM strike marker</td></tr><tr><td><strong>OI Range</strong></td><td><code>/oirange</code></td><td>OI by strike over a custom range, with ATM-relative selectors and optional one-minute auto-refresh</td></tr><tr><td><strong>OI Profile</strong></td><td><code>/oiprofile</code></td><td>Futures candlesticks with an OI butterfly and daily OI change across strikes</td></tr><tr><td><strong>GEX Dashboard</strong></td><td><code>/gex</code></td><td>Gamma exposure with OI walls, net GEX per strike and the top gamma strikes</td></tr><tr><td><strong>Gamma Density</strong></td><td><code>/gammadensity</code></td><td>Gamma times OI density and convexity zones, intraday and to-expiry, with ATM IV and expected-move bands</td></tr></tbody></table><h2 id="straddles-and-spreads" tabindex="-1">Straddles and Spreads <a class="header-anchor" href="#straddles-and-spreads" aria-label="Permalink to &quot;Straddles and Spreads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Path</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Straddle Chart</strong></td><td><code>/straddle</code></td><td>Dynamic ATM straddle with rolling strike, spot and synthetic futures overlay</td></tr><tr><td><strong>Straddle PnL</strong></td><td><code>/straddlepnl</code></td><td>Simulated intraday ATM straddle P&amp;L with automated adjustments and a trade log</td></tr><tr><td><strong>Arbitrage</strong></td><td><code>/arbitrage</code></td><td>Real-time futures calendar-spread scanner across NFO and MCX, ranked by executable bid and ask spread</td></tr></tbody></table><h2 id="strategy-building" tabindex="-1">Strategy Building <a class="header-anchor" href="#strategy-building" aria-label="Permalink to &quot;Strategy Building&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Path</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Strategy Builder</strong></td><td><code>/strategybuilder</code></td><td>Multi-leg option strategies with live Greeks, payoff diagram and what-if simulators</td></tr><tr><td><strong>Strategy Portfolio</strong></td><td><code>/strategybuilder/portfolio</code></td><td>Saved strategies across MyTrades and Simulation watchlists</td></tr></tbody></table><h2 id="portfolio-and-backtesting" tabindex="-1">Portfolio and Backtesting <a class="header-anchor" href="#portfolio-and-backtesting" aria-label="Permalink to &quot;Portfolio and Backtesting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Path</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Portfolio Backtester</strong></td><td><code>/portfolio-backtester</code></td><td>Weighted portfolio against an index with real delivery costs, rebalancing rules, crisis periods and a full tearsheet</td></tr><tr><td><strong>SIP Backtester</strong></td><td><code>/sip-backtester</code></td><td>What a monthly, weekly or quarterly SIP would have returned: XIRR, rupee-cost averaging, start-date sensitivity and a lumpsum comparison</td></tr><tr><td><strong>Portfolio Analyzer</strong></td><td><code>/portfolio-analyzer</code></td><td>Grades the holdings you actually own: concentration, co-movement, drawdown resilience and behaviour in past crises</td></tr></tbody></table><hr><h2 id="what-these-tools-need" tabindex="-1">What These Tools Need <a class="header-anchor" href="#what-these-tools-need" aria-label="Permalink to &quot;What These Tools Need&quot;">​</a></h2><p><strong>A connected broker.</strong> The options tools read the live option chain, so they need a broker session with market-data entitlement for the relevant exchange. A plugin that does not cover NFO or MCX cannot feed the tools that depend on it. See <a href="./connect-brokers/brokers/README">Brokers</a> for per-plugin exchange coverage.</p><p><strong>Local history, for the backtesters.</strong> The portfolio and SIP backtesters read stored data by default rather than calling the broker on every run. Download the range you need with <a href="./new-features/historify">Historify</a> first.</p><p><strong>Nothing else.</strong> There is no external data vendor, no subscription and no account beyond your own broker.</p><hr><h2 id="automating-what-you-see" tabindex="-1">Automating What You See <a class="header-anchor" href="#automating-what-you-see" aria-label="Permalink to &quot;Automating What You See&quot;">​</a></h2><p>Several tools have a REST equivalent, so a strategy can consume the same numbers the screen shows:</p><table tabindex="0"><thead><tr><th>Tool</th><th>API</th></tr></thead><tbody><tr><td>Option Chain</td><td><a href="./api-documentation/v1/data-api/option-chain">Option Chain</a></td></tr><tr><td>Option Greeks</td><td><a href="./api-documentation/v1/data-api/optiongreeks">OptionGreeks</a> and <a href="./api-documentation/v1/data-api/multioptiongreeks">MultiOptionGreeks</a></td></tr><tr><td>Straddle and synthetic futures</td><td><a href="./api-documentation/v1/data-api/syntheticfuture">SyntheticFuture</a></td></tr><tr><td>SIP Backtester</td><td><a href="./api-documentation/v1/utilities-api/sip-backtest">SIP Backtest</a></td></tr></tbody></table><p>The Greeks endpoints are rate limited separately and more tightly than general data endpoints. See <a href="./api-documentation/v1/rate-limiting">Rate Limiting</a> before polling them in a loop.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./why-to-build-with-tradeboard">Why to Build with Tradeboard?</a></li><li><a href="./new-features/trading-terminal">Chart Trading Terminal</a> for trading from the chart itself</li><li><a href="./new-features/fast-scalper">Scalping Terminal</a> for keyboard-driven execution</li></ul>',27)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
